#ifndef CTCP_TX_APP_H
#define CTCP_TX_APP_H

#include "CTCPInstructions.h"
#include "ns3/mt-txapp.h"

#include <queue>
#include <unordered_map>

/**
 * @brief CTCP app-facing sink that stores feedback generated by processors.
 */
class CTCPTXApp : public ns3::MTTXAppScheduler {
public:
    CTCPTXApp() = default;

    /**
     * @brief Consume a TXAPP instruction and enqueue feedback by flow.
     */
    void execute_instr(ns3::MTInstruction *instr) override;

    /**
     * @brief Feedback queue API
     * True when feedback is waiting for a flow.
     */
    bool HasFeedback(flow_id fid) const;
    /**
     * @brief Pop one feedback item for a flow.
     */
    bool PopFeedback(flow_id fid, FB_INSTR &out);
    /**
     * @brief Number of queued feedback items for a flow.
     */
    size_t FeedbackCount(flow_id fid) const;

private:
    std::unordered_map<flow_id, std::queue<FB_INSTR>, flow_id_hash> feedback_;
};

#endif // CTCP_TX_APP_H
